// #bb57bd מסך אשף Onboarding — «сервер в памяти» для мастера /onboarding под ADMIN компании A.
// ДАННЫЕ ПРОФИЛЯ ADMIN НЕ МЕНЯЮТСЯ: каждый POST (upsert) в rest/v1/company_profiles перехватывается и НЕ уходит
// на сервер — запоминается в памяти теста и отвечает 201. Следующие GET company_profiles идут на сервер, но в ответе
// details подменяется последним сохранённым в памяти (так проверяется «сохранить и продолжить позже»).
// Любая другая запись в Supabase (rest/storage, кроме входа auth/v1/token) прерывается и считается в blockedWrites —
// тест должен проверять, что их 0.
import { Page, expect } from '@playwright/test';

export const STEPS = ['פרטי חברה', 'מידע להתאמת מכרזים', 'גורמים מקצועיים קבועים', 'מסמכים קבועים'] as const;
export const SAVE_LATER = 'שמירה והמשך מאוחר יותר';
export const FINISH = 'סיום והקמת הפרופיל';
export const SAVING = 'שומר…';

type Onboarding = { step: number; completed: boolean; completedSteps: number[] };
type Details = Record<string, unknown> & { onboarding?: Onboarding };

export type WizardServer = {
  /** Тела перехваченных POST company_profiles по порядку (на сервер не ушли). */
  saves: { legal_name?: string; registration_number?: string; details: Details }[];
  /** Последнее onboarding из перехваченных сохранений. */
  lastOnboarding: () => Onboarding | undefined;
  /** Перехваченные прочие записи (должно быть 0). */
  blockedWrites: string[];
  /** Задерживать ответ на следующие сохранения, пока не вызван release(). */
  hold: () => { release: () => void };
};

const PROFILES = /\/rest\/v1\/company_profiles(\?|$)/;
const WRITE = (m: string) => !['GET', 'HEAD', 'OPTIONS'].includes(m);

/**
 * Включить «сервер в памяти». fresh — с первого GET показать мастер как у новой компании
 * (onboarding: шаг 1, ни одного пройденного шага), не трогая остальные данные профиля.
 */
export async function mockWizardServer(page: Page, opts: { fresh?: boolean } = {}): Promise<WizardServer> {
  const saves: WizardServer['saves'] = [];
  const blockedWrites: string[] = [];
  let gate: Promise<void> | null = null;

  // Предохранитель: все прочие записи в Supabase не пропускаем (регистрируется первым — срабатывает последним).
  await page.route(/supabase\.co\/(rest|storage)\/v1\//, async (route) => {
    const r = route.request();
    if (WRITE(r.method())) {
      blockedWrites.push(`${r.method()} ${r.url()}`);
      return route.abort();
    }
    return route.fallback();
  });

  await page.route(PROFILES, async (route) => {
    const r = route.request();
    if (WRITE(r.method())) {
      saves.push(JSON.parse(r.postData() ?? '{}'));
      if (gate) await gate;
      return route.fulfill({ status: 201, body: '' });
    }
    const res = await route.fetch();
    const rows = (await res.json()) as Record<string, unknown>[];
    const last = saves[saves.length - 1];
    const patched = rows.map((row) => {
      if (last) {
        const next: Record<string, unknown> = { ...row, details: last.details };
        if ('legal_name' in row && last.legal_name !== undefined) next.legal_name = last.legal_name;
        if ('registration_number' in row && last.registration_number !== undefined) next.registration_number = last.registration_number;
        return next;
      }
      if (opts.fresh) {
        const details = { ...((row.details as Details) ?? {}), onboarding: { step: 0, completed: false, completedSteps: [] } };
        return { ...row, details };
      }
      return row;
    });
    return route.fulfill({ response: res, json: patched });
  });

  return {
    saves,
    blockedWrites,
    lastOnboarding: () => saves[saves.length - 1]?.details?.onboarding,
    hold: () => {
      let release!: () => void;
      gate = new Promise<void>((r) => (release = r));
      return {
        release: () => {
          gate = null;
          release();
        },
      };
    },
  };
}

export const stepper = (page: Page) => page.getByRole('list', { name: 'שלבי האשף' });
export const stepItems = (page: Page) => stepper(page).getByRole('listitem');
export const stepHeading = (page: Page) => page.getByRole('heading', { level: 2, name: /^שלב \d מתוך 4:/ });
export const stepRegion = (page: Page) => page.getByRole('region', { name: /^שלב \d מתוך 4:/ });
export const btn = (page: Page, name: string) => stepRegion(page).getByRole('button', { name, exact: true });

/** Открыт шаг n (1..4): заголовок «שלב n מתוך 4: <название>», aria-current="step" только у n-го пункта. */
export async function expectStep(page: Page, n: number) {
  await expect(stepHeading(page)).toHaveText(`שלב ${n} מתוך 4: ${STEPS[n - 1]}`);
  const items = stepItems(page);
  await expect(items).toHaveCount(4);
  for (let i = 0; i < 4; i++) {
    if (i === n - 1) await expect(items.nth(i)).toHaveAttribute('aria-current', 'step');
    else await expect(items.nth(i)).not.toHaveAttribute('aria-current', /.+/);
  }
}

/** ✓ ровно у пунктов из done (номера 1..4), у остальных нет. */
export async function expectDone(page: Page, done: number[]) {
  const items = stepItems(page);
  for (let i = 0; i < 4; i++) {
    const name = STEPS[i];
    if (done.includes(i + 1)) await expect(items.nth(i), `✓ у «${name}»`).toHaveText(new RegExp(`^✓\\s*${name}$`));
    else await expect(items.nth(i), `нет ✓ у «${name}»`).not.toContainText('✓');
  }
}

/** Нажать кнопку шага и дождаться перехвата сохранения. */
export async function clickAndSave(page: Page, server: WizardServer, name: string) {
  const before = server.saves.length;
  await btn(page, name).click();
  await expect.poll(() => server.saves.length, { message: `после «${name}» нет сохранения` }).toBeGreaterThan(before);
}

